_PccuEntry('CPAP and BiPAP basics', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['CPAP improves oxygenation and splints airways; BiPAP adds inspiratory pressure support to improve ventilation.','Best suited to a cooperative child with intact airway reflexes and reversible respiratory failure.']), _PccuSection('Initial stabilization', <String>['Use experienced staff, correct interface and continuous monitoring.','Typical editable starting points: CPAP 5–8 cmH₂O; BiPAP EPAP 5–8 and IPAP 8–12 cmH₂O, then titrate to response and local protocol.']), _PccuSection('Disease-specific treatment / settings', <String>['Treat agitation non-pharmacologically first; sedation can precipitate airway loss and requires PCCU-level monitoring.','Provide gastric decompression if significant distension.']), _PccuSection('Monitoring', <String>['SpO₂, respiratory effort, synchrony, leak, skin pressure points, blood gas and hemodynamics.']), _PccuSection('Expected response', <String>['Improved ventilation/oxygenation, lower work of breathing and good patient-device synchrony.']), _PccuSection('Failure criteria and escalation', <String>['Inability to protect airway, copious secretions, recurrent vomiting, worsening acidosis, shock, apnea or intolerance despite optimization.']), _PccuSection('Complications / cautions', <String>['Aspiration, pressure injury, gastric distension, air leak and delayed intubation.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local NIV policy.'])], 'CPAP AND BIPAP BASICS\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific CPAP and BiPAP basics pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Non-invasive ventilation troubleshooting', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Troubleshoot in a fixed sequence: patient, interface, circuit, settings, then disease progression.']), _PccuSection('Initial stabilization', <String>['Check airway patency, secretion burden, mask position, leak, exhalation port, humidification and circuit disconnection.','Confirm trigger sensitivity, rise time, backup rate and inspiratory/expiratory pressures match the child.']), _PccuSection('Disease-specific treatment / settings', <String>['Correct agitation drivers such as hypoxemia, pain, fever, urinary retention and mask discomfort.','Escalate rather than repeatedly increasing pressures when physiology worsens.']), _PccuSection('Monitoring', <String>['Waveforms, delivered tidal volume, leak percentage, SpO₂, RR, gas exchange and mental status.']), _PccuSection('Expected response', <String>['Improved synchrony and lower work of breathing after the identified issue is corrected.']), _PccuSection('Failure criteria and escalation', <String>['Persistent large leak, poor synchrony, worsening gas, declining consciousness, apnea or shock.']), _PccuSection('Complications / cautions', <String>['Barotrauma, gastric insufflation, pressure injury and delayed invasive ventilation.']), _PccuSection('Sources and local verification', <String>['Local ventilator/NIV manual; RCUK 2025 PLS.'])], 'NON-INVASIVE VENTILATION TROUBLESHOOTING\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Non-invasive ventilation troubleshooting pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Indications for intubation', 'Respiratory Support', <_PccuSection>[_PccuSection('Clinical overview', <String>['Intubate for failure of oxygenation, ventilation or airway protection, or when anticipated deterioration makes controlled airway management safer than rescue intubation.']), _PccuSection('Initial stabilization', <String>['Call experienced airway/PCCU/anesthesia support early and use a checklist.','Preoxygenate with the best tolerated method, optimize hemodynamics and prepare backup airway plans.']), _PccuSection('Disease-specific treatment / settings', <String>['Common triggers: refractory hypoxemia, severe hypercapnic acidosis with fatigue, recurrent apnea, GCS decline, uncontrolled status epilepticus, shock requiring airway control, or upper-airway obstruction.']), _PccuSection('Monitoring', <String>['Continuous ECG, SpO₂, BP and waveform capnography; document first-pass success and complications.']), _PccuSection('Expected response', <String>['Confirmed tube position with sustained waveform capnography and improved oxygenation/ventilation.']), _PccuSection('Failure criteria and escalation', <String>['Failed first attempt, severe desaturation, hypotension, bradycardia, cannot intubate/cannot oxygenate.']), _PccuSection('Complications / cautions', <String>['Hypoxemia, hypotension, bradycardia, aspiration, esophageal or mainstem intubation and airway trauma.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; Difficult Airway Society pediatric guidance; local RSI protocol.'])], 'INDICATIONS FOR INTUBATION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Indications for intubation pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
