_PccuEntry('Status asthmaticus', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Status asthmaticus is severe asthma not responding adequately to initial bronchodilator and steroid therapy.']), _PccuSection('Initial stabilization', <String>['Continue oxygen, continuous inhaled beta-agonist, ipratropium for the initial severe phase, systemic steroid and IV magnesium.','Involve PCCU/respiratory therapy early and correct dehydration/electrolyte abnormalities cautiously.']), _PccuSection('Disease-specific treatment / settings', <String>['Consider IV salbutamol/terbutaline or aminophylline only under local specialist protocols.','NIV may help selected cooperative patients but can worsen air trapping; intubation is high risk and should be performed by an experienced team.']), _PccuSection('Monitoring', <String>['Serial examination, gas trend, potassium, lactate, ECG, fluid balance, expiratory flow and auto-PEEP if ventilated.']), _PccuSection('Expected response', <String>['Falling bronchodilator requirement, better air entry and resolving acidosis without fatigue.']), _PccuSection('Failure criteria and escalation', <String>['Altered consciousness, refractory hypoxemia, progressive hypercapnia/acidosis, exhaustion or arrest.']), _PccuSection('Complications / cautions', <String>['Dynamic hyperinflation, hypotension, barotrauma, beta-agonist toxicity and mucus plugging.']), _PccuSection('Sources and local verification', <String>['GINA 2025; local PICU status-asthmaticus pathway.'])], 'STATUS ASTHMATICUS\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Status asthmaticus pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Bronchiolitis requiring HFNC', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Use HFNC for persistent hypoxemia or significant work of breathing after suctioning and low-flow oxygen, not solely for a diagnostic label.']), _PccuSection('Initial stabilization', <String>['Minimal handling, nasal suction, hydration support and appropriate isolation.','Start weight-based heated humidified flow per local protocol and titrate FiO₂ to the prescribed saturation target.']), _PccuSection('Disease-specific treatment / settings', <String>['Bronchodilators, steroids and antibiotics are not routine unless another diagnosis or clear response supports them.','Use NG/IV fluids based on work of breathing and aspiration risk.']), _PccuSection('Monitoring', <String>['Apnea, RR, HR, retractions, FiO₂, feeding tolerance and hydration; reassess within 30–60 minutes.']), _PccuSection('Expected response', <String>['Lower RR/HR and work of breathing with stable oxygenation.']), _PccuSection('Failure criteria and escalation', <String>['Recurrent apnea, escalating FiO₂/flow, fatigue, worsening gas exchange or shock.']), _PccuSection('Complications / cautions', <String>['Air leak, abdominal distension, secretion obstruction and delayed CPAP/intubation.']), _PccuSection('Sources and local verification', <String>['AAP/RCH bronchiolitis guidance; local HFNC pathway.'])], 'BRONCHIOLITIS REQUIRING HFNC\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Bronchiolitis requiring HFNC pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Severe pneumonia', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Consider bacterial, viral, aspiration and complicated pneumonia; assess for effusion, empyema, necrosis and sepsis.']), _PccuSection('Initial stabilization', <String>['Oxygen/respiratory support, cultures when feasible before antibiotics, prompt empiric antimicrobials and fluid/perfusion assessment.','Use ultrasound or chest imaging when complications are suspected.']), _PccuSection('Disease-specific treatment / settings', <String>['Antibiotic choice should follow age, immunization, local resistance, MRSA risk and aspiration context.','Drain significant complicated effusion/empyema with respiratory/surgical/interventional input.']), _PccuSection('Monitoring', <String>['SpO₂, work of breathing, perfusion, lactate, urine output, inflammatory markers and imaging trajectory when complicated.']), _PccuSection('Expected response', <String>['Falling oxygen need, improved work of breathing and perfusion within the expected interval.']), _PccuSection('Failure criteria and escalation', <String>['Escalating support, shock, rising lactate, enlarging effusion, air leak or multiorgan dysfunction.']), _PccuSection('Complications / cautions', <String>['Empyema, necrotizing pneumonia, pneumothorax, ARDS and septic shock.']), _PccuSection('Sources and local verification', <String>['IDSA/PIDS pediatric CAP guidance; local antimicrobial and empyema pathways.'])], 'SEVERE PNEUMONIA\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Severe pneumonia pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Pediatric ARDS', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Diagnose using PALICC-2 criteria in a child with acute hypoxemic respiratory failure not fully explained by cardiac failure or fluid overload.']), _PccuSection('Initial stabilization', <String>['Use lung-protective ventilation based on ideal body weight, adequate PEEP and the lowest FiO₂ that achieves the selected target.','Avoid unnecessary fluid accumulation and treat the precipitating cause.']), _PccuSection('Disease-specific treatment / settings', <String>['Tidal volume commonly 4–8 mL/kg depending on compliance; limit plateau/driving pressure according to local protocol.','Consider prone positioning for severe oxygenation failure and discuss inhaled pulmonary vasodilator, HFOV or ECMO in refractory cases.']), _PccuSection('Monitoring', <String>['OI/OSI trend, plateau pressure, driving pressure, compliance, gas exchange, fluid balance and right-heart function.']), _PccuSection('Expected response', <String>['Improving OI/OSI and FiO₂ requirement without injurious pressure.']), _PccuSection('Failure criteria and escalation', <String>['Progressive OI/OSI, refractory hypoxemia, severe acidosis, barotrauma or hemodynamic compromise.']), _PccuSection('Complications / cautions', <String>['Ventilator-induced lung injury, air leak, fluid overload, pulmonary hypertension and multiorgan dysfunction.']), _PccuSection('Sources and local verification', <String>['PALICC-2 2023; institutional pediatric ARDS protocol.'])], 'PEDIATRIC ARDS\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Pediatric ARDS pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Croup requiring advanced airway support', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Severe croup includes stridor at rest with marked retractions, fatigue, hypoxemia or reduced air entry.']), _PccuSection('Initial stabilization', <String>['Keep the child calm, provide dexamethasone and nebulized epinephrine, and involve anesthesia/ENT/PCCU early.','Avoid upsetting examinations or procedures until the airway team is ready.']), _PccuSection('Disease-specific treatment / settings', <String>['Prepare a smaller-than-age-predicted ETT because of subglottic edema; use the most experienced airway operator.']), _PccuSection('Monitoring', <String>['Continuous SpO₂, stridor, air entry, mental status and recurrence after epinephrine.']), _PccuSection('Expected response', <String>['Sustained reduction in stridor and work of breathing after observation.']), _PccuSection('Failure criteria and escalation', <String>['Exhaustion, cyanosis, altered consciousness, poor air entry or recurrent severe obstruction.']), _PccuSection('Complications / cautions', <String>['Rapid airway obstruction, post-intubation edema and unplanned extubation.']), _PccuSection('Sources and local verification', <String>['RCH croup guideline; local difficult-airway protocol.'])], 'CROUP REQUIRING ADVANCED AIRWAY SUPPORT\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Croup requiring advanced airway support pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Upper-airway obstruction', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Differentiate croup, anaphylaxis, epiglottitis/bacterial tracheitis, foreign body, abscess and post-extubation edema.']), _PccuSection('Initial stabilization', <String>['Call anesthesia/ENT/PCCU early, keep the child upright and calm, and avoid airway agitation.','Give condition-specific therapy such as IM epinephrine for anaphylaxis or nebulized epinephrine/dexamethasone for croup.']), _PccuSection('Disease-specific treatment / settings', <String>['Do not force throat examination when epiglottitis or critical obstruction is suspected.','Prepare for controlled airway management in the operating room/PICU when feasible.']), _PccuSection('Monitoring', <String>['Stridor, voice, drooling, air entry, mental status, SpO₂ and hemodynamics.']), _PccuSection('Expected response', <String>['Improving air entry and reduced stridor without fatigue.']), _PccuSection('Failure criteria and escalation', <String>['Silent obstruction, cyanosis, bradycardia, altered consciousness or inability to maintain oxygenation.']), _PccuSection('Complications / cautions', <String>['Complete obstruction, aspiration and traumatic airway attempts.']), _PccuSection('Sources and local verification', <String>['RCUK 2025 PLS; local ENT/difficult-airway pathway.'])], 'UPPER-AIRWAY OBSTRUCTION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Upper-airway obstruction pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Aspiration', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Aspiration may cause acute obstruction, chemical pneumonitis, bacterial pneumonia or ARDS.']), _PccuSection('Initial stabilization', <String>['Suction visible material, support oxygenation/ventilation and evaluate for foreign body or ongoing aspiration.','Bronchoscopy is indicated when particulate obstruction or foreign body is suspected.']), _PccuSection('Disease-specific treatment / settings', <String>['Antibiotics are not automatically required for uncomplicated chemical pneumonitis; use when bacterial infection is suspected or established.']), _PccuSection('Monitoring', <String>['SpO₂, work of breathing, fever, gas exchange and radiographic progression when severe.']), _PccuSection('Expected response', <String>['Improving oxygenation and respiratory effort over hours with supportive care.']), _PccuSection('Failure criteria and escalation', <String>['Persistent focal obstruction, worsening oxygen requirement, shock or evolving ARDS.']), _PccuSection('Complications / cautions', <String>['Pneumonia, abscess, ARDS and recurrent aspiration.']), _PccuSection('Sources and local verification', <String>['Local aspiration/foreign-body and antimicrobial guidance.'])], 'ASPIRATION\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Aspiration pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Pulmonary hemorrhage', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Treat frank airway bleeding with hypoxemia as a life-threatening airway and circulation emergency.']), _PccuSection('Initial stabilization', <String>['Call PCCU/respiratory/hematology, give high-concentration oxygen, secure airway if needed and correct coagulopathy.','Use large-bore suction and isolate the bleeding lung when anatomically possible.']), _PccuSection('Disease-specific treatment / settings', <String>['Ventilation may require higher PEEP; bronchoscopy/interventional radiology/surgery may be required.','Review anticoagulants, platelet count, coagulation, vasculitis and cardiac causes.']), _PccuSection('Monitoring', <String>['Hemoglobin, coagulation, gas exchange, airway pressures, hemodynamics and bleeding volume.']), _PccuSection('Expected response', <String>['Bleeding slows, oxygenation stabilizes and transfusion requirement falls.']), _PccuSection('Failure criteria and escalation', <String>['Ongoing large-volume bleeding, refractory hypoxemia, shock or airway obstruction.']), _PccuSection('Complications / cautions', <String>['Asphyxia, severe anemia, ARDS and recurrent hemorrhage.']), _PccuSection('Sources and local verification', <String>['Local massive hemoptysis/pulmonary hemorrhage protocol.'])], 'PULMONARY HEMORRHAGE\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Pulmonary hemorrhage pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
_PccuEntry('Neuromuscular respiratory failure', 'Disease-Specific Respiratory Pathways', <_PccuSection>[_PccuSection('Clinical overview', <String>['Look for weak cough, bulbar dysfunction, shallow breathing, paradoxical movement and declining vital capacity rather than relying on SpO₂ alone.']), _PccuSection('Initial stabilization', <String>['Involve neurology/respiratory/PCCU, support secretion clearance and monitor ventilation.','Use NIV early in selected cooperative patients without major bulbar dysfunction.']), _PccuSection('Disease-specific treatment / settings', <String>['Avoid excessive oxygen without ventilation assessment because hypercapnia may worsen unnoticed.','Plan intubation before profound fatigue or secretion-related collapse.']), _PccuSection('Monitoring', <String>['Serial gas/ETCO₂, cough strength, secretion burden, vital capacity or negative inspiratory force where feasible.']), _PccuSection('Expected response', <String>['Improved ventilation and secretion clearance with stable bulbar function.']), _PccuSection('Failure criteria and escalation', <String>['Rising CO₂, weak cough, recurrent atelectasis, aspiration, inability to clear secretions or reduced consciousness.']), _PccuSection('Complications / cautions', <String>['Mucus plugging, aspiration, atelectasis and difficult weaning.']), _PccuSection('Sources and local verification', <String>['Local neuromuscular respiratory-failure guidance.'])], 'NEUROMUSCULAR RESPIRATORY FAILURE\\n- ABCDE stabilization and confirm current measured weight.\\n- Apply the disease-specific Neuromuscular respiratory failure pathway and local formulary/equipment standards.\\n- Define objective monitoring targets and a reassessment interval.\\n- Escalate to senior/PCCU support for failure criteria or deterioration.\\n- Verify all doses, concentrations and settings independently.'),
