  _PccuEntry entry(String title) => entries.firstWhere((item) => item.title == title);

  void openEntry(String title) {
    Navigator.of(context).push(MaterialPageRoute<void>(builder: (_) => _PccuDetailScreen(entry: entry(title))));
  }

  @override
  Widget build(BuildContext context) {
    final normalized = query.trim().toLowerCase();
    final matches = normalized.isEmpty ? const <_PccuEntry>[] : entries.where((e) => ('${e.title} ${e.category} ${e.searchText}').toLowerCase().contains(normalized)).toList();
    return Scaffold(
      appBar: AppBar(title: const Text('PCCU')),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 32),
        children: <Widget>[
          Card(color: Theme.of(context).colorScheme.errorContainer, child: const Padding(padding: EdgeInsets.all(16), child: Text('Rapid clinical decision support only. Verify doses, concentrations, ventilator settings, procedures and escalation thresholds against current local PCCU protocols, pharmacy and senior guidance.'))),
          const SizedBox(height: 12),
          TextField(onChanged: (value) => setState(() => query = value), decoration: const InputDecoration(prefixIcon: Icon(Icons.search), labelText: 'Search PCCU topics', border: OutlineInputBorder())),
          if (normalized.isNotEmpty) ...<Widget>[
            const SizedBox(height: 10),
            ...matches.map((e) => Card(child: ListTile(title: Text(e.title), subtitle: Text(e.category), trailing: const Icon(Icons.chevron_right), onTap: () => openEntry(e.title)))),
            if (matches.isEmpty) const Card(child: Padding(padding: EdgeInsets.all(14), child: Text('No PCCU topic matched this search.'))),
          ],
          const SizedBox(height: 20),
          Text('Emergency shortcuts', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w900)),
          const SizedBox(height: 10),
          LayoutBuilder(
            builder: (context, constraints) {
              final int columns = constraints.maxWidth >= 900 ? 4 : 2;
              return GridView.count(
                crossAxisCount: columns,
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                crossAxisSpacing: 12,
                mainAxisSpacing: 12,
                childAspectRatio: columns == 4 ? 2.5 : 2.2,
                children: <Widget>[
                  _shortcut('INTUBATION', Icons.air, 'Pediatric rapid-sequence intubation'),
                  _shortcut('SEPTIC SHOCK', Icons.monitor_heart, 'Septic shock'),
                  _shortcut('STATUS EPILEPTICUS', Icons.bolt, 'Status epilepticus'),
                  _shortcut('CARDIAC ARREST', Icons.favorite, 'Bradycardia'),
                ],
              );
            },
          ),
          const SizedBox(height: 22),
          Text('PCCU Sections', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w900)),
          const SizedBox(height: 10),
          ...categories.map((category) => Card(child: ExpansionTile(leading: Icon(category.icon), title: Text(category.title, style: const TextStyle(fontWeight: FontWeight.w800)), subtitle: Text('${category.topics.length} topics'), children: category.topics.map((title) => ListTile(title: Text(title), trailing: const Icon(Icons.chevron_right), onTap: () => openEntry(title))).toList()))),
        ],
      ),
    );
  }

  Widget _shortcut(String label, IconData icon, String title) => FilledButton.tonalIcon(
    onPressed: () => openEntry(title),
    icon: Icon(icon),
    label: Padding(
      padding: const EdgeInsets.symmetric(vertical: 12),
      child: FittedBox(
        fit: BoxFit.scaleDown,
        child: Text(label, textAlign: TextAlign.center),
      ),
    ),
  );
}

class PccuCalculatorsScreen extends StatelessWidget {
  const PccuCalculatorsScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final items = <({String title, String subtitle, IconData icon, Widget screen})>[
      (title: 'Vasoactive infusion calculator', subtitle: 'Dose, concentration and pump-rate conversion', icon: Icons.medication, screen: const _VasoactiveInfusionCalculator()),
      (title: 'Ventilator starting suggestions', subtitle: 'Editable disease-specific initial decision support', icon: Icons.settings_input_component, screen: const _VentilatorPresetCalculator()),
      (title: 'Oxygenation index', subtitle: 'MAP × FiO₂ × 100 ÷ PaO₂', icon: Icons.show_chart, screen: const _OxygenationIndexCalculator()),
      (title: 'Oxygen-saturation index', subtitle: 'MAP × FiO₂ × 100 ÷ SpO₂', icon: Icons.monitor_heart_outlined, screen: const _OsiCalculator()),
      (title: 'P/F and S/F ratios', subtitle: 'PaO₂/FiO₂ and SpO₂/FiO₂', icon: Icons.analytics_outlined, screen: const _OxygenRatioCalculator()),
      (title: 'Vasoactive-inotropic score', subtitle: 'Standard VIS calculation', icon: Icons.speed, screen: const _VisCalculator()),
      (title: 'Fluid balance and urine output', subtitle: 'Net balance, mL/kg and mL/kg/hour', icon: Icons.water, screen: const _FluidBalanceCalculator()),
      (title: 'ET tube estimate', subtitle: 'Age-based cuffed/uncuffed size and oral depth', icon: Icons.straighten, screen: const _EttCalculator()),
      (title: 'Defibrillation and cardioversion', subtitle: 'Weight-based energy display', icon: Icons.electric_bolt, screen: const _CardioversionCalculator()),
      (title: 'Adenosine calculator', subtitle: 'Weight-based dose with maximum-dose display', icon: Icons.favorite, screen: const _AdenosineCalculator()),
      (title: 'Prostaglandin E1 infusion', subtitle: 'Dose and concentration to mL/hour', icon: Icons.child_care, screen: const _PgeCalculator()),
      (title: 'Corrected QT', subtitle: 'Bazett and Fridericia estimates', icon: Icons.monitor_heart_outlined, screen: const _QtcCalculator()),
      (title: 'Glasgow Coma Scale', subtitle: 'Eye, verbal and motor total', icon: Icons.psychology, screen: const _GcsCalculator()),
    ];

    return Scaffold(
      appBar: AppBar(title: const Text('PCCU & Critical Care Calculators')),
      body: ListView.separated(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
        itemCount: items.length,
        separatorBuilder: (_, __) => const SizedBox(height: 10),
        itemBuilder: (context, index) {
          final item = items[index];
          return Card(
            child: ListTile(
              leading: CircleAvatar(child: Icon(item.icon)),
              title: Text(item.title, style: const TextStyle(fontWeight: FontWeight.w800)),
              subtitle: Text(item.subtitle),
              trailing: const Icon(Icons.chevron_right),
              onTap: () => Navigator.of(context).push(
                MaterialPageRoute<void>(builder: (_) => item.screen),
              ),
            ),
          );
        },
      ),
    );
  }
}

class _PccuCategory { final String title; final IconData icon; final List<String> topics; const _PccuCategory(this.title, this.icon, this.topics); }
class _PccuSection { final String heading; final List<String> bullets; const _PccuSection(this.heading, this.bullets); }
class _PccuEntry {
  final String title; final String category; final List<_PccuSection> sections; final String copyPlan;
  const _PccuEntry(this.title, this.category, this.sections, this.copyPlan);
  String get searchText => sections.expand((s) => <String>[s.heading, ...s.bullets]).join(' ');
}

class _PccuDetailScreen extends StatelessWidget {
  final _PccuEntry entry;
  const _PccuDetailScreen({required this.entry});
  @override Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: Text(entry.title)),
    body: ListView(padding: const EdgeInsets.all(16), children: <Widget>[
      Text(entry.category, style: Theme.of(context).textTheme.labelLarge),
      const SizedBox(height: 8),
      Card(color: Theme.of(context).colorScheme.errorContainer, child: const Padding(padding: EdgeInsets.all(14), child: Text('Initial decision support—not an automatic prescription. Apply current local protocols and obtain senior/PCCU support when indicated.'))),
      const SizedBox(height: 10),
      ...entry.sections.map((section) => Card(child: ExpansionTile(initiallyExpanded: section.heading == 'Initial approach / settings' || section.heading == 'Escalation triggers', title: Text(section.heading, style: const TextStyle(fontWeight: FontWeight.w800)), children: section.bullets.map((b) => ListTile(leading: const Icon(Icons.check_circle_outline), title: Text(b))).toList()))),
      const SizedBox(height: 10),
      FilledButton.icon(onPressed: () async { await Clipboard.setData(ClipboardData(text: entry.copyPlan)); if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('PCCU plan copied'))); }, icon: const Icon(Icons.copy), label: const Text('Copy PCCU plan')),
    ]),
  );
}

abstract class _CalcState<T extends StatefulWidget> extends State<T> {
  Widget field(TextEditingController c, String label, {String? suffix}) => Padding(padding: const EdgeInsets.only(bottom: 12), child: TextField(controller: c, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: InputDecoration(labelText: label, suffixText: suffix, border: const OutlineInputBorder())));
  Widget result(String text) => text.isEmpty ? const SizedBox.shrink() : Card(child: Padding(padding: const EdgeInsets.all(16), child: SelectableText(text, style: const TextStyle(height: 1.45))));
}

