us'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>disease=v!),decoration:const InputDecoration(labelText:'Disease pattern',border:OutlineInputBorder())),const SizedBox(height:12),FilledButton(onPressed:calc,child:const Text('Generate starting suggestions')),const SizedBox(height:12),result(output)]));}

